def transform(grid):
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            colors = {v for line in grid[r:r+3] for v in line[c:c+3]} - {0, 5}
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out
